package com.manishrawat.realestate.filter; import jakarta.servlet.*; import jakarta.servlet.annotation.WebFilter; import jakarta.servlet.http.*; import java.io.*;
@WebFilter(urlPatterns={"/dashboard","/logout","/property","/application","/admin","/manager","/tenant"}) public class AuthFilter implements Filter {public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;HttpServletResponse s=(HttpServletResponse)res;if(r.getSession().getAttribute("user")==null){s.sendRedirect(r.getContextPath()+"/");return;}chain.doFilter(req,res);}}
